/* Complete Arb scatter construction. No floating arithmetic in certificates. */
#include <flint/arb.h>
#include <flint/arf.h>
#include <flint/fmpz.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>
#define N 690988
#define PREC 192
#define BITS 56
static int p[4]={2,3,5,7};
static arb_ptr amp;
static int *rr,*om,*smooth,ns;
static unsigned char (*ex)[4];
static int maxraw[4]={19,12,8,6},maxe[4]={7,4,3,2};
static void truncval(FILE *f,const char *name,const arb_t v){
 arf_t q;arf_init(q);fmpz_t a,b,ten;fmpz_init(a);fmpz_init(b);fmpz_init(ten);fmpz_set_ui(ten,1000000000000UL);
 arb_t z;arb_init(z);arb_mul_fmpz(z,v,ten,PREC);
 arb_get_lbound_arf(q,z,PREC);arf_get_fmpz(a,q,ARF_RND_FLOOR);arb_get_ubound_arf(q,z,PREC);arf_get_fmpz(b,q,ARF_RND_CEIL);
 fprintf(f,"%s ",name);fmpz_fprint(f,a);fprintf(f," ");fmpz_fprint(f,b);fprintf(f,"\n");
 arb_clear(z);arf_clear(q);fmpz_clear(a);fmpz_clear(b);fmpz_clear(ten);
}
static void bounds(FILE*f,const arb_t v){
 arb_t z;arb_init(z);arb_mul_2exp_si(z,v,BITS);arf_t a;arf_init(a);fmpz_t l,h;fmpz_init(l);fmpz_init(h);
 arb_get_lbound_arf(a,z,PREC);arf_get_fmpz(l,a,ARF_RND_FLOOR);arb_get_ubound_arf(a,z,PREC);arf_get_fmpz(h,a,ARF_RND_CEIL);
 fmpz_fprint(f,l);fputc(' ',f);fmpz_fprint(f,h);fputc('\n',f);arb_clear(z);arf_clear(a);fmpz_clear(l);fmpz_clear(h);
}
static void make_amp(long num,long den){
 arb_t x,c,t,l,z,q,pi;arb_init(x);arb_init(c);arb_init(t);arb_init(l);arb_init(z);arb_init(q);arb_init(pi);
 arb_set_str(x,"6000000185827",PREC);arb_mul(q,x,x,PREC);arb_add_ui(q,q,1,PREC);arb_sqrt(c,q,PREC);arb_const_pi(pi,PREC);arb_mul_ui(pi,pi,4,PREC);arb_div(c,c,pi,PREC);arb_log(c,c,PREC);arb_div_ui(c,c,4,PREC);arb_inv(q,q,PREC);arb_div_ui(q,q,2,PREC);arb_sub(c,c,q,PREC);arb_set_si(t,num);arb_div_ui(t,t,den,PREC);
 for(int n=1;n<=N;n++){arb_set_ui(l,n);arb_log(l,l,PREC);arb_mul(z,l,l,PREC);arb_div_ui(z,z,4,PREC);arb_mul(q,c,l,PREC);arb_sub(z,z,q,PREC);arb_mul(z,z,t,PREC);arb_div_ui(q,l,2,PREC);arb_sub(z,z,q,PREC);arb_exp(amp+n,z,PREC);}
 arb_clear(x);arb_clear(c);arb_clear(t);arb_clear(l);arb_clear(z);arb_clear(q);arb_clear(pi);
}
static long encode(const int *v,const int *mx){long z=0;for(int j=0;j<4;j++){assert(v[j]>=-mx[j]&&v[j]<=mx[j]);z=z*(2*mx[j]+1)+v[j]+mx[j];}return z;}
static void decode(long k,int*v,const int*mx){for(int j=3;j>=0;j--){int d=2*mx[j]+1;v[j]=k%d-mx[j];k/=d;}}
static long size(const int*mx){long z=1;for(int j=0;j<4;j++)z*=2*mx[j]+1;return z;}
static long diff(int s,int t,const int*mx){int v[4];for(int j=0;j<4;j++)v[j]=(int)ex[s][j]-(int)ex[t][j];return encode(v,mx);}
int main(void){
 flint_set_num_threads(1);rr=calloc(N+1,sizeof(int));om=calloc(N+1,sizeof(int));ex=calloc(N+1,sizeof(*ex));smooth=calloc(N+1,sizeof(int));amp=_arb_vec_init(N+1);
 for(int n=1;n<=N;n++){int r=n;for(int j=0;j<4;j++)while(r%p[j]==0){r/=p[j];ex[n][j]++;om[n]++;}rr[n]=r;if(r==1)smooth[ns++]=n;}assert(ns==1160);
 FILE* summary=fopen("primary_summary.txt","w");assert(summary);arb_t a,b,z,q,W,cp,cm,star,vstar;arb_init(a);arb_init(b);arb_init(z);arb_init(q);arb_init(W);arb_init(cp);arb_init(cm);arb_init(star);arb_init(vstar);
 make_amp(13,80);arb_zero(a);arb_zero(b);for(int n=1;n<=N;n++){arb_add(b,b,amp+n,PREC);if(rr[n]==1)arb_add(a,a,amp+n,PREC);}arb_mul_ui(a,a,2,PREC);arb_sub(a,a,b,PREC);truncval(summary,"anchor745",a);
 make_amp(4,25);FILE* raw=fopen("primary_raw.txt","w");for(int n=1;n<=N;n++){fprintf(raw,"%d ",n);bounds(raw,amp+n);}fclose(raw);
 arb_ptr plus=_arb_vec_init(N+1),minus=_arb_vec_init(N+1),v=_arb_vec_init(N+1);int nr=0;
 for(int n=1;n<=N;n++){arb_add(plus+rr[n],plus+rr[n],amp+n,PREC);if(om[n]&1)arb_sub(minus+rr[n],minus+rr[n],amp+n,PREC);else arb_add(minus+rr[n],minus+rr[n],amp+n,PREC);}
 arb_set(cp,plus+1);arb_set(cm,minus+1);assert(arb_is_positive(cp)&&arb_is_positive(cm));arb_set_ui(star,1);arb_div_ui(star,star,10,PREC);
 for(int r=2;r<=N;r++)if(rr[r]==r){nr++;arb_div(a,plus+r,cp,PREC);arb_mul(a,a,a,PREC);arb_mul_ui(a,a,8,PREC);arb_div(b,minus+r,cm,PREC);arb_mul(b,b,b,PREC);arb_add(a,a,b,PREC);arb_div_ui(a,a,9,PREC);arb_sqrt(v+r,a,PREC);assert(arb_is_positive(v+r));arb_add(W,W,v+r,PREC);}
 arb_div(a,star,cp,PREC);arb_mul(a,a,a,PREC);arb_mul_ui(a,a,8,PREC);arb_div(b,star,cm,PREC);arb_mul(b,b,b,PREC);arb_add(a,a,b,PREC);arb_div_ui(a,a,9,PREC);arb_sqrt(vstar,a,PREC);arb_add(W,W,vstar,PREC);
 assert(nr==157939);truncval(summary,"core_plus",cp);truncval(summary,"core_minus",cm);truncval(summary,"weight_sum",W);truncval(summary,"synthetic_v",vstar);
 FILE*vw=fopen("primary_weights.txt","w");fprintf(vw,"0 ");bounds(vw,vstar);for(int r=2;r<=N;r++)if(rr[r]==r){fprintf(vw,"%d ",r);bounds(vw,v+r);}fclose(vw);
 long sz=size(maxraw);arb_ptr four=_arb_vec_init(sz);uint64_t covered=0,sum=0,squares=0;long npairs=0;
 for(int r=1;r<=N;r++)if(rr[r]==r){int m=0;while(m<ns&&smooth[m]<=N/r)m++;covered+=m;for(int i=0;i<m;i++){long n=(long)r*smooth[i];sum+=n;squares+=(uint64_t)n*n;}
  if(r==1)arb_one(q);else{arb_div(q,W,v+r,PREC);arb_neg(q,q);}
  for(int i=0;i<m;i++){arb_mul(a,q,amp+(long)r*smooth[i],PREC);for(int j=i;j<m;j++){arb_mul(b,a,amp+(long)r*smooth[j],PREC);long k=diff(smooth[i],smooth[j],maxraw);arb_add(four+k,four+k,b,PREC);if(j!=i){k=diff(smooth[j],smooth[i],maxraw);arb_add(four+k,four+k,b,PREC);}npairs++;}}
 }
 assert(covered==N&&sum==(uint64_t)N*(N+1)/2&&squares==(uint64_t)N*(N+1)*(2*N+1)/6);
 int zz[4]={0,0,0,0};long zero=encode(zz,maxraw);arb_div(a,W,vstar,PREC);arb_div_ui(a,a,100,PREC);arb_sub(four+zero,four+zero,a,PREC);
 printf("COMPLETE_RAW_SUPPORT %llu PAIRS %ld\n",(unsigned long long)covered,npairs);fflush(stdout);
 int nd=0;while(smooth[nd]<=128)nd++;assert(nd==53);arb_ptr lam=_arb_vec_init(nd);arb_one(lam);for(int j=1;j<nd;j++){int d=smooth[j];for(int i=0;i<j;i++)if(d%smooth[i]==0){arb_mul(a,lam+i,amp+d/smooth[i],PREC);arb_sub(lam+j,lam+j,a,PREC);}}
 FILE*iv=fopen("primary_inverse.txt","w");for(int i=0;i<nd;i++){fprintf(iv,"%d ",smooth[i]);bounds(iv,lam+i);}fclose(iv);
 /* Independent755 signed complete core moment, no recut. */
 int maxp[4];for(int j=0;j<4;j++)maxp[j]=maxraw[j]+maxe[j];long sp=size(maxp);arb_ptr core=_arb_vec_init(sp);
 for(int i=0;i<nd;i++)for(int j=0;j<ns;j++){int e[4];for(int k=0;k<4;k++)e[k]=ex[smooth[i]][k]+ex[smooth[j]][k];long ix=encode(e,maxp);arb_mul(a,lam+i,amp+smooth[j],PREC);arb_add(core+ix,core+ix,a,PREC);}
 arb_zero(a);arb_zero(b);arb_t edge;arb_init(edge);for(int j=0;j<ns;j++){arb_mul_ui(z,amp+smooth[j],om[smooth[j]]*om[smooth[j]],PREC);arb_add(a,a,z,PREC);}for(long i=0;i<sp;i++)if(!arb_is_zero(core+i)){int e[4],omega=0;decode(i,e,maxp);uint64_t prod=1;for(int k=0;k<4;k++){assert(e[k]>=0);omega+=e[k];for(int l=0;l<e[k];l++)prod*=p[k];}arb_abs(z,core+i);if(prod>N)arb_add(edge,edge,z,PREC);arb_mul_ui(z,z,omega*omega,PREC);arb_add(b,b,z,PREC);}
 truncval(summary,"anchor755_oldmoment",a);truncval(summary,"anchor755_newmoment",b);arb_div(z,b,a,PREC);truncval(summary,"anchor755_ratio",z);truncval(summary,"anchor755_edge",edge);_arb_vec_clear(core,sp);
 /* Complete |E|^2 convolution of the signed raw Gram polynomial. */
 long se=size(maxe);arb_ptr efour=_arb_vec_init(se);for(int i=0;i<nd;i++)for(int j=0;j<nd;j++){arb_mul(a,lam+i,lam+j,PREC);long k=diff(smooth[i],smooth[j],maxe);arb_add(efour+k,efour+k,a,PREC);}
 long *ir=malloc(sz*sizeof(long)),*ie=malloc(se*sizeof(long));int (*er)[4]=malloc(sz*sizeof(*er)),(*ee)[4]=malloc(se*sizeof(*ee));long rn=0,en=0;
 for(long j=0;j<sz;j++)if(!arb_is_zero(four+j)){ir[rn]=j;decode(j,er[rn++],maxraw);}for(long j=0;j<se;j++)if(!arb_is_zero(efour+j)){ie[en]=j;decode(j,ee[en++],maxe);}
 arb_ptr out=_arb_vec_init(sp);for(long i=0;i<rn;i++)for(long j=0;j<en;j++){int e[4];for(int k=0;k<4;k++)e[k]=er[i][k]+ee[j][k];long k=encode(e,maxp);arb_mul(a,four+ir[i],efour+ie[j],PREC);arb_add(out+k,out+k,a,PREC);}
 FILE*ff=fopen("primary_fourier.txt","w");long count=0;for(long k=0;k<sp;k++)if(!arb_is_zero(out+k)){int e[4];decode(k,e,maxp);fprintf(ff,"%d %d %d %d ",e[0],e[1],e[2],e[3]);bounds(ff,out+k);count++;}fclose(ff);
 fprintf(summary,"counts %d %d %d %ld %ld %ld %ld\n",ns,nr,nd,npairs,rn,en,count);fclose(summary);printf("COMPLETE_FOURIER raw=%ld inverse_square=%ld final=%ld\n",rn,en,count);fflush(stdout);
 return 0;
}

#!/usr/bin/python3
"""Complete independent smooth-pair gather in Arb256; completed-square amplitudes."""
from flint import arb,ctx
from fractions import Fraction as Q
from pathlib import Path
import json,hashlib,time
ctx.prec=256;ctx.threads=1
N=690988;P=(2,3,5,7);BITS=56
st=time.process_time()
def aq(q):q=Q(q);return arb(q.numerator)/q.denominator
def digits(x):
 lo=Q(str(x.lower().fmpq()));hi=Q(str(x.upper().fmpq()));return [lo.numerator*10**12//lo.denominator,-((-hi).numerator*10**12//(-hi).denominator)]
def bounds(x):
 lo=(x*(1<<BITS)).lower().floor().unique_fmpz();hi=(x*(1<<BITS)).upper().ceil().unique_fmpz();assert lo is not None and hi is not None;return str(lo)+' '+str(hi)
# Recursive smooth enumeration versus primary per-n division.
support={1:(0,0,0,0)}
for j,p in enumerate(P):
 for n,e in list(support.items()):
  m=n;v=list(e)
  while m<=N//p:m*=p;v[j]+=1;support[m]=tuple(v)
S=sorted(support);assert len(S)==1160
rough=[r for r in range(1,N+1) if all(r%p for p in P)]
rough_nonunit=rough[1:]
logs=[arb(0)]+[arb(i).log() for i in range(1,N+1)]
pi=16*(arb(1)/5).atan()-4*(arb(1)/239).atan();x=arb(6000000185827)
# c expressed without sqrt; independent normalization.
c=((1+x*x).log()/2-(4*pi).log())/4-1/(2*(1+x*x))
def amplitudes(t):
 t=aq(t);b=2*c+1/t;off=-t*b*b/4
 # n=1 has exact log1=0, hence a1=1; preserve this exact boundary.
 return [arb(0),arb(1)]+[(t*(l-b)**2/4+off).exp() for l in logs[2:]]
summary={}
a=amplitudes('13/80');summary['anchor745']=digits(2*sum((a[s] for s in S),arb(0))-sum(a,arb(0)))
a=amplitudes('4/25')
with Path('secondary_raw.txt').open('w') as f:
 for n in range(1,N+1):f.write(str(n)+' '+bounds(a[n])+'\n')
plus={};minus={};seen=cntsum=sumsq=0
for s in reversed(S):
 sg=-1 if sum(support[s])%2 else 1
 for r in rough:
  n=r*s
  if n>N:break
  plus[r]=plus.get(r,arb(0))+a[n];minus[r]=minus.get(r,arb(0))+sg*a[n]
  seen+=1;cntsum+=n;sumsq+=n*n
assert seen==N and cntsum==N*(N+1)//2 and sumsq==N*(N+1)*(2*N+1)//6
cp=plus[1];cm=minus[1];assert cp>0 and cm>0
v={r:((8*(plus[r]/cp)**2+(minus[r]/cm)**2)/9).sqrt() for r in rough_nonunit}
vstar=((8/cp**2+1/cm**2)/900).sqrt();W=sum(v.values(),vstar);v[0]=vstar
for name,z in [('core_plus',cp),('core_minus',cm),('weight_sum',W),('synthetic_v',vstar)]:summary[name]=digits(z)
with Path('secondary_weights.txt').open('w') as f:
 for r in sorted(v):f.write(str(r)+' '+bounds(v[r])+'\n')
# Gram matrix gathered by smooth pair. All rough contributions present.
scales={r:W/v[r] for r in rough_nonunit};H={};pairs=0
for j,s in enumerate(S):
 for d in S[:j+1]:
  z=a[s]*a[d]
  for r in rough_nonunit:
   if r>N//s:break
   z-=scales[r]*a[r*s]*a[r*d]
  e=tuple(support[s][k]-support[d][k] for k in range(4));H[e]=H.get(e,arb(0))+z
  if d!=s:
   ne=tuple(-q for q in e);H[ne]=H.get(ne,arb(0))+z
  pairs+=1
H[(0,0,0,0)]-=W/(100*vstar)
print('SECONDARY COMPLETE GRAM',len(H),'CPU',time.process_time()-st,flush=True)
# Geometric formal series for inverse, independent recurrence.
D=[s for s in S if s<=128];lam={1:arb(1)};power={1:arb(1)}
for deg in range(1,8):
 nxt={}
 for d,u in power.items():
  for s in D[1:]:
   if d*s>128:break
   nxt[d*s]=nxt.get(d*s,arb(0))-u*a[s]
 for d,u in nxt.items():lam[d]=lam.get(d,arb(0))+u
 power=nxt
assert set(lam)==set(D)
with Path('secondary_inverse.txt').open('w') as f:
 for d in D:f.write(str(d)+' '+bounds(lam[d])+'\n')
# Whole convolution core and matching accepted755 controls.
cs=sorted(set(d*s for d in D for s in S));old=sum((a[s]*sum(support[s])**2 for s in S),arb(0));new=arb(0);edge=arb(0)
for m in cs:
 z=sum((lam[d]*a[m//d] for d in D if m%d==0 and m//d in support),arb(0));mm=m;omega=0
 for p in P:
  while mm%p==0:mm//=p;omega+=1
 assert mm==1
 new+=abs(z)*omega**2
 if m>N:edge+=abs(z)
for name,z in [('anchor755_oldmoment',old),('anchor755_newmoment',new),('anchor755_ratio',new/old),('anchor755_edge',edge)]:summary[name]=digits(z)
# |E|^2 via real autocorrelation, then output-coefficient gather rather than scatter.
C={}
for d in D:
 for s in D:
  e=tuple(support[d][k]-support[s][k] for k in range(4));C[e]=C.get(e,arb(0))+lam[d]*lam[s]
# Sparse two-stage scatter: first multiply E, then its conjugate. Different summation and factorization from primary.
G={}
for d in D:
 e=support[d];ll=lam[d]
 for f,z in H.items():
  ee=tuple(f[k]+e[k] for k in range(4));G[ee]=G.get(ee,arb(0))+ll*z
T={}
for d in reversed(D):
 e=support[d];ll=lam[d]
 for f,z in G.items():
  ee=tuple(f[k]-e[k] for k in range(4));T[ee]=T.get(ee,arb(0))+ll*z
with Path('secondary_fourier.txt').open('w') as f:
 for e,z in sorted(T.items()):f.write(' '.join(map(str,e))+' '+bounds(z)+'\n')
summary['counts']=[len(S),len(rough)-1,len(D),len(H),len(C),len(T)];Path('secondary_summary.json').write_text(json.dumps(summary,indent=2)+'\n');print('SECONDARY COMPLETE',len(T),'CPU',time.process_time()-st,flush=True)

/* Exact integer interval jets with Arb Taylor completion on all closed leaves. */
#include <flint/arb.h>
#include <flint/arf.h>
#include <flint/fmpz.h>
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#define PREC 192
#define SCALE 56
#define TRIG 40
#define DEN (1LL<<TRIG)
#define CAP 150000
static void sint(char*b,__int128 n){char t[80];int j=0,neg=n<0;unsigned __int128 u=neg?-n:n;do{t[j++]='0'+u%10;u/=10;}while(u);int k=0;if(neg)b[k++]='-';while(j)b[k++]=t[--j];b[k]=0;}
static void aset(arb_t a,__int128 n,int b){char s[80];sint(s,n);arb_set_str(a,s,PREC);arb_mul_2exp_si(a,a,-b);}
static void interval(arb_t a,__int128 l,__int128 h,int b){arb_t x;arb_init(x);aset(a,l,b);aset(x,h,b);arb_union(a,a,x,PREC);arb_clear(x);}
static void floors(FILE*f,const arb_t a){arb_t z;arb_init(z);arb_mul_ui(z,a,1000000000000UL,PREC);arf_t a1;arf_init(a1);fmpz_t i;fmpz_init(i);arb_get_lbound_arf(a1,z,PREC);arf_get_fmpz(i,a1,ARF_RND_FLOOR);fmpz_fprint(f,i);fputc(' ',f);arb_get_ubound_arf(a1,z,PREC);arf_get_fmpz(i,a1,ARF_RND_CEIL);fmpz_fprint(f,i);arb_clear(z);arf_clear(a1);fmpz_clear(i);}
static void tr(arb_t x,int64_t*lo,int64_t*hi){arb_mul_2exp_si(x,x,TRIG);arf_t a;arf_init(a);fmpz_t b;fmpz_init(b);arb_get_lbound_arf(a,x,PREC);arf_get_fmpz(b,a,ARF_RND_FLOOR);assert(fmpz_fits_si(b));*lo=fmpz_get_si(b);arb_get_ubound_arf(a,x,PREC);arf_get_fmpz(b,a,ARF_RND_CEIL);assert(fmpz_fits_si(b));*hi=fmpz_get_si(b);arf_clear(a);fmpz_clear(b);}
static void mul(int64_t a,int64_t b,int64_t c,int64_t d,__int128*l,__int128*h){__int128 v[4]={(__int128)a*c,(__int128)a*d,(__int128)b*c,(__int128)b*d};*l=*h=v[0];for(int i=1;i<4;i++){if(v[i]<*l)*l=v[i];if(v[i]>*h)*h=v[i];}}
static void addmul(__int128*l,__int128*h,__int128 a,__int128 b,int64_t m){if(m>=0){*l+=a*m;*h+=b*m;}else{*l+=b*m;*h+=a*m;}}
static int fact(int n){int r=1;for(int i=2;i<=n;i++)r*=i;return r;}
int main(void){
 flint_set_num_threads(1);FILE*f=fopen("primary_fourier.txt","r");assert(f);int (*e)[4]=malloc(CAP*sizeof(*e));int64_t*lo=malloc(CAP*sizeof(int64_t)),*hi=malloc(CAP*sizeof(int64_t));int n=0;int z[4];long long l,h;__int128 tail=0;
 while(fscanf(f,"%d %d %d %d %lld %lld",z,z+1,z+2,z+3,&l,&h)==6){assert(l<=h);int pos=0;for(int j=0;j<4;j++)if(z[j]){pos=z[j]>0?1:-1;break;}if(pos<0)continue;int mulc=pos?2:1;int64_t am=llabs(l)>llabs(h)?llabs(l):llabs(h);
  if((__int128)am*10000000000LL<(1LL<<SCALE)){tail+=(__int128)mulc*am;continue;}
  for(int j=0;j<4;j++){assert(abs(z[j])<=26);e[n][j]=z[j];}assert(l>-(1LL<<60)&&h<(1LL<<60));lo[n]=l*mulc;hi[n]=h*mulc;n++;assert(n<CAP);
 }fclose(f);
 int multi[70][4],deg[70],fac[70],nt=0,nlow=0;
 for(int dd=0;dd<=4;dd++)for(int a=0;a<=dd;a++)for(int b=0;b<=dd-a;b++)for(int c=0;c<=dd-a-b;c++){int d=dd-a-b-c;multi[nt][0]=a;multi[nt][1]=b;multi[nt][2]=c;multi[nt][3]=d;deg[nt]=dd;fac[nt]=fact(a)*fact(b)*fact(c)*fact(d);nt++;if(dd<=3)nlow++;}assert(nt==70&&nlow==35);
 int64_t (*mon)[35]=malloc(n*sizeof(*mon));__int128 M4[35]={0},absjet[35]={0};
