#!/usr/bin/python3
"""Own exact dyadic phase recurrence, every closed leaf, exact torus occupancy.
All original first/second derivative tables compared by authenticated digests;
all original leaf lower expressions reconstructed, plus an independent tight line.
"""
from pathlib import Path
import json,hashlib,itertools,math,subprocess,time
from fractions import Fraction as Q
from qinterval import I,pi,export,floor_trunc,ceil_trunc,decimal
F=Path('frozen'); start=time.process_time()

def signed_bin(z,p):
    return floor_trunc(z.lower*(1<<p),0),ceil_trunc(z.upper*(1<<p),0)
def decode(k,p):return I(Q(k[0],1<<p),Q(k[1],1<<p))
def loads(p):return json.loads(Path(p).read_text())
def digits(z,places=12):return floor_trunc(z.lower,places),ceil_trunc(z.upper,places)
def exact_export(q,places=12):
    q=Q(q);return {'exact':str(q),'FLOOR'+str(places):decimal(floor_trunc(q,places),places),'CEIL'+str(places):decimal(ceil_trunc(q,places),places)}

def phase_table():
    # cos(pi/32) via three positive half-angle roots starting from cos(pi/4).
    c=I(2).sqrt()/2
    for _ in range(3): c=((1+c)/2).sqrt()
    s=((1-c)*(1+c)).sqrt()
    arr=[];re,im=I(1),I(0)
    for k in range(64):
        # Algebraic exact axis points remove accumulated dependency at zero.
        if k%16==0: re,im=map(I,[(1,0),(0,1),(-1,0),(0,-1)][k//16])
        arr.append((re,im));re,im=re*c-im*s,im*c+re*s
    return arr

def check_coverage(boxes):
    assert len(boxes)==len(set(tuple(tuple(a) for a in b) for b in boxes))
    M=max(d for b in boxes for d,m in b);grid=1<<M
    # Four-dimensional cubical cellular cover by bitset union, no inherited occupancy code.
    slices=[0]*(grid**3);maskfull=(1<<grid)-1;volume=Q(0)
    for box in boxes:
        ranges=[]
        for d,m in box:
            assert 0<=d<=M and 0<=m<1<<d
            ranges.append(range(m*(1<<(M-d)),(m+1)*(1<<(M-d))))
        mm=((1<<len(ranges[3]))-1)<<ranges[3].start
        for a,b,c in itertools.product(*ranges[:3]):
            idx=(a*grid+b)*grid+c
            if slices[idx]&mm:raise ValueError('interior overlap')
            slices[idx]|=mm
        volume+=Q(1,1<<sum(d for d,m in box))
    if not all(s==maskfull for s in slices):raise ValueError('uncovered elementary cell')
    assert volume==1
    # all faces of the cell partition included because boxes declared closed.
    return {'max_depth':M,'elementary_cells':grid**4,'sum_exact_volume':str(volume),'closed_boxes':len(boxes),'all_faces_closed':True}

def parameters():
    arr=[]
    for d in range(5):
        for a in itertools.product(range(5),repeat=4):
            if sum(a)==d:arr.append(a)
    assert len(arr)==70
    return arr

def execute(compile_c=True):
    boxes=loads(F/'m767_LEAVES.json')['boxes']; cov=check_coverage(boxes)
    # Geometry mutations prove this coverage check can fail without a numerical marker.
    rejected=0
    for test in [boxes[:-1],boxes+[boxes[0]],boxes[1:]+[boxes[0],boxes[0]]]:
        try:check_coverage(test)
        except (ValueError,AssertionError):rejected+=1
        else:raise AssertionError('inert coverage test')
    assert rejected==3
    with Path('LEAF_INPUTS.txt').open('w') as f:
        for j,b in enumerate(boxes):f.write(str(j)+' '+' '.join(str(z) for a in b for z in a)+'\n')
    phases=phase_table();bins={p:[(signed_bin(a,p),signed_bin(b,p)) for a,b in phases] for p in [40,60]}
    # Original Arb tables may put an infinitesimal interval around exact trig zeros.
    # Own table uses exact axes; reproduce their printed 40bit cells where valid.
    orig={}
    for label in ['primary','secondary']:
        table=[list(map(int,line.split())) for line in (F/f'm767_{label}_trig.txt').read_text().splitlines()]
        assert len(table)==64
        for row,((cl,ch),(sl,sh)) in zip(table,bins[40]):
            k,l,u,a,b=row
            assert l<=cl<=ch<=u and a<=sl<=sh<=b,(label,k,row,bins[40][k])
        orig[label]=table
    assert orig['primary']==orig['secondary']
    with Path('TRIG_INPUTS.txt').open('w') as f:
        for row in orig['primary']:f.write('40 '+' '.join(map(str,row))+'\n')
        for k,((cl,ch),(sl,sh)) in enumerate(bins[60]):f.write(f'60 {k} {cl} {ch} {sl} {sh}\n')
    if compile_c:
        subprocess.run(['gcc','-O2','-std=c11','-Wall','-Wextra','-Werror','-fsanitize=undefined','-fno-sanitize-recover=all','residue_jets.c','-o','residue_jets'],check=True)
        subprocess.run(['./residue_jets'],check=True,timeout=360)
    # Every original jet row, not just selected spots, is compared by byte digest.
    pins=loads('INPUT_PINS.json');alljetcounts={}
    for label in ['primary','secondary']:
        text=Path(label.upper()+'_REPRO_JETS.txt').read_bytes()
        h=hashlib.sha256(text).hexdigest()
        original=pins['frozen/m767_spot_'+label+'_jets.txt']['full_original_sha256']
        assert h==original,(label,h,original)
        selected={int(l.split()[0]) for l in (F/f'm767_spot_{label}_jets.txt').read_text().splitlines()}
        spot=''.join(l for l in text.decode().splitlines(True) if int(l.split()[0]) in selected)
        assert spot==(F/f'm767_spot_{label}_jets.txt').read_text()
        alljetcounts[label]={'count':text.count(b'\n'),'sha256':h,'selected_original_leaves':len(selected)}
        print('ORIGINAL_ALL_JETS_MATCH',label,text.count(b'\n'),h,flush=True)
    budget=Path('JET_BUDGETS.txt').read_text().splitlines();n,kept,tail=map(int,budget[0].split());assert n==len(boxes)
    fourth=list(map(int,budget[1:]));assert len(fourth)==35
    alpha=parameters();power_cache={}
    P=pi()
    # Scalar Taylor coefficients h^alpha/alpha! depend only on depth vector.
    for b in boxes:
        ds=tuple(d for d,m in b)
        if ds in power_cache:continue
        h=[P/(1<<d) for d in ds]
        coefficients=[]
        for a in alpha:
            z=I(1)
            for j in range(4):z=z*h[j]**a[j]/math.factorial(a[j])
            coefficients.append(z)
        power_cache[ds]=coefficients
    sheets={};snapshot={};minimums={};minidx={}
    # Source primary stores an interval EXPRESSION: |jet interval| has a nonzero width;
    # secondary stores a lower-endpoint expression. Reconstruct their exact formula separately.
    files={'primary':'PRIMARY_REPRO_JETS.txt','secondary':'SECONDARY_REPRO_JETS.txt','own':'OWN_JETS.txt'}
    for label,name in files.items():
        data=[list(map(int,l.split())) for l in Path(name).read_text().splitlines()]
        assert len(data)==35*len(boxes)
        scalebits={'primary':96,'secondary':98,'own':116}[label]
        original_rows=None
        if label!='own':original_rows=[list(map(int,l.split())) for l in (F/f'm767_{label}_leaves.txt').read_text().splitlines()]
        values=[];rec=[]
        for i,box in enumerate(boxes):
            jet=[]
            for j in range(35):
                a,b,l,u=data[35*i+j];assert a==i and b==j and l<=u;jet.append((l,u))
            K=power_cache[tuple(d for d,m in box)]
            if label=='primary':z=decode(jet[0],scalebits)
            else:z=I(Q(jet[0][0],1<<scalebits))
            z-=I(Q(tail,1<<56))
            for j in range(1,35):
                if label=='primary':a=abs(decode(jet[j],scalebits))
                else:a=I(Q(max(abs(jet[j][0]),abs(jet[j][1])),1<<scalebits))
                z-=a*K[j]
            for j in range(35):z-=I(Q(fourth[j],1<<56))*K[j+35]
            assert z>I(Q(1,1000000)),(label,i,export(z,12))
            digs=digits(z)
            if original_rows is not None:assert [i,*digs]==original_rows[i],(label,i,digs,original_rows[i])
            values.append(z);rec.append([i,*digs])
        # min of lower expressions; machine derives aggregate, never inferred from summary text.
        li=min(range(len(values)),key=lambda i:values[i].a)
        minimums[label]=export(I(min(v.a for v in values),min(v.b for v in values),raw=True),12);minidx[label]=li
        sheets[label]=rec
        print('ALL_CLOSED_LEAVES',label,len(values),'MINIMUM_LEAF',li,'FLOOR12',minimums[label]['floor'],'CEIL12',minimums[label]['ceil'],flush=True)
        snapshot[label]=[export(values[i],12) for i in loads('ORIGINAL_SPOTS.json')['indices']]
    # Live primary/secondary summaries consumed only after all leaves independently checked.
    old=loads(F/'m767_SUMMARY.json')
    for label in ['primary','secondary']:
        assert minimums[label]['floor']==old[label+'_minimum_lower_expression']['FLOOR12']
        assert minimums[label]['ceil']==old[label+'_minimum_lower_expression']['CEIL12']
    assert Q(tail,1<<56)==Q(old['discarded_l1_exact_upper'])
    assert kept==old['kept_half_terms'] and len(boxes)*35==old['jet_enclosures']
    report={'arithmetic':'integer/dyadic; signed residue buckets; non-producer exact half-angle phase recurrence','coverage':cov,'coverage_adverse_rejections':rejected,'jet_tables':alljetcounts,'kept_half_terms':kept,'discarded_l1':exact_export(Q(tail,1<<56)),'minimum_expressions':minimums,'minimum_leaf_indices':minidx,'original_leaf_digits_all_equal':True,'all_leaf_threshold':'1/1000000','spot_original_inputs':loads('ORIGINAL_SPOTS.json'),'spot_expressions':snapshot,'leaf_depth_patterns':len(power_cache)}
    Path('LEAF_RESULTS.json').write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
    Path('OWN_LEAF_PAIRS.json').write_text(json.dumps(sheets,separators=(',',':'))+'\n')
    print('WHOLE_TORUS_CERTIFIED',cov['elementary_cells'],'CLOSED_LEAVES',len(boxes),'CPU',time.process_time()-start,flush=True)
    return report

if __name__=='__main__':execute()

"""Independent integer endpoint arithmetic. No Arb, mpmath, or producer helper.
All endpoints are integers times 2^-P. Every division rounds outward.
Transcendentals use the explicit rational remainders proved in ARITHMETIC.md.
"""
from fractions import Fraction
from math import isqrt, factorial
from functools import lru_cache
P = 272
S = 1 << P

def down(n,d):
    if d <= 0: raise ValueError('positive denominator required')
    return n//d

def up(n,d):
    return -down(-n,d)

class I:
    __slots__=('a','b')
    def __init__(self,x=0,y=None,raw=False):
        if raw:
            self.a,self.b=int(x),int(y)
        else:
            if isinstance(x,I):
                if y is not None: raise TypeError('ambiguous interval')
                self.a,self.b=x.a,x.b
            else:
                if isinstance(x,float) or isinstance(y,float): raise TypeError('no floating inputs')
                l=Fraction(x); h=l if y is None else Fraction(y)
                self.a=down(l.numerator*S,l.denominator)
                self.b=up(h.numerator*S,h.denominator)
        if self.a>self.b: raise ValueError('reversed interval')
    @property
    def lower(self): return Fraction(self.a,S)
    @property
    def upper(self): return Fraction(self.b,S)
    def __add__(self,z):
        z=I(z); return I(self.a+z.a,self.b+z.b,raw=True)
    __radd__=__add__
    def __neg__(self): return I(-self.b,-self.a,raw=True)
    def __sub__(self,z): return self+-I(z)
    def __rsub__(self,z): return I(z)+-self
    def __mul__(self,z):
        z=I(z); e=(self.a*z.a,self.a*z.b,self.b*z.a,self.b*z.b)
        return I(down(min(e),S),up(max(e),S),raw=True)
    __rmul__=__mul__
    def reciprocal(self):
        if self.a<=0<=self.b: raise ValueError('division by zero enclosure')
        def point(q,upper):
            n,d=S*S,q
            if d<0: n,d=-n,-d
            return up(n,d) if upper else down(n,d)
        return I(point(self.b,False),point(self.a,True),raw=True)
    def __truediv__(self,z): return self*I(z).reciprocal()
    def __rtruediv__(self,z): return I(z)*self.reciprocal()
    def __pow__(self,n):
        if not isinstance(n,int): raise TypeError('integer powers only')
        if n<0: return self.reciprocal()**(-n)
        r=I(1); b=self
        while n:
            if n&1: r=r*b
            b=b*b; n//=2
        return r
    def __lt__(self,z): return self.b<I(z).a
    def __le__(self,z): return self.b<=I(z).a
    def __gt__(self,z): return I(z)<self
    def __ge__(self,z): return I(z)<=self
    def __abs__(self):
        if self.a>=0: return I(self)
        if self.b<=0: return -self
        return I(0,max(-self.a,self.b),raw=True)
    def contains(self,z):
        z=I(z); return self.a<=z.a and z.b<=self.b
    def overlaps(self,z):
        z=I(z); return self.a<=z.b and z.a<=self.b
    def sqrt(self):
        if self.a<0: raise ValueError('sqrt negative interval')
        a=isqrt(self.a*S); b=isqrt(self.b*S)
        if b*b<self.b*S: b+=1
        return I(a,b,raw=True)
    def log(self):
        if self.a<=0: raise ValueError('log nonpositive interval')
        l=log_point(self.lower); h=log_point(self.upper)
        return I(l.a,h.b,raw=True)
    def exp(self):
        l=exp_point(self.lower); h=exp_point(self.upper)
        return I(l.a,h.b,raw=True)
    def atan(self):
        l=atan_point(self.lower); h=atan_point(self.upper)
        return I(l.a,h.b,raw=True)
    def asin(self):
        if not(-1<self<1): raise ValueError('strict asin domain')
        return (self/(1-self*self).sqrt()).atan()
    def cos_small(self):
        if not(0<=self<=1): raise ValueError('cos_small domain [0,1]')
        l=cos_point(self.upper); h=cos_point(self.lower)
        return I(l.a,h.b,raw=True)
    def __repr__(self): return 'I('+str(self.lower)+','+str(self.upper)+')'

@lru_cache(maxsize=1024)
def log_point(q):
    q=Fraction(q)
    if q<=0: raise ValueError('log domain')
    n,d=q.numerator,q.denominator
    e=n.bit_length()-d.bit_length()
    if e>=0:
        if n<(d<<e): e-=1
    elif (n<<(-e))<d: e-=1
    r=q/Fraction(2**e) if e>=0 else q*(1<<(-e))
    assert 1<=r<2
    return log_normal(r)+e*log_two()

def log_normal(q):
    if not 1<=q<=2: raise ValueError('log reduction')
    z=I((q-1)/(q+1)); z2=z*z; term=z; total=I(0)
    M=160
    for j in range(M):
        total+=term/(2*j+1); term=term*z2
    rem=Fraction(2,1)*Fraction(1,3)**(2*M+1)/((2*M+1)*(1-Fraction(1,9)))
    return 2*total+I(0,rem)

@lru_cache(maxsize=1)
def log_two(): return log_normal(Fraction(2))

@lru_cache(maxsize=1024)
def exp_point(q):
    q=Fraction(q)
    if q<0: return exp_point(-q).reciprocal()
    if q==0: return I(1)
    j=0
    while q/(1<<j)>Fraction(1,8): j+=1
    z=I(q/(1<<j)); total=I(1); term=I(1); M=96
    for k in range(1,M+1):
        term=term*z/k; total+=term
    rem=2*Fraction(1,8)**(M+1)/factorial(M+1)
    total+=I(0,rem)
    for _ in range(j): total=total*total
    return total

def atan_series(q):
    q=Fraction(q)
    if q<0: return -atan_series(-q)
    if q>Fraction(1,2): raise ValueError('atan series domain')
    z=I(q); z2=z*z; term=z; total=I(0); M=192
    for j in range(M):
        total+=(term/(2*j+1)) if j%2==0 else -(term/(2*j+1))
        term=term*z2
    # M even: partial sum below the exact alternating series.
    return total+I(0,q**(2*M+1)/(2*M+1))

@lru_cache(maxsize=1)
def pi(): return 16*atan_series(Fraction(1,5))-4*atan_series(Fraction(1,239))

@lru_cache(maxsize=1024)
def atan_point(q):
    q=Fraction(q)
    if q<0: return -atan_point(-q)
    if q<=Fraction(1,2): return atan_series(q)
    if q>=2: return pi()/2-atan_series(1/q)
    return pi()/4+atan_series((q-1)/(q+1))

def cos_point(q):
    q=Fraction(q)
    if not 0<=q<=1: raise ValueError('cos series domain')
    z=I(q); zz=z*z; term=I(1); total=I(1); M=100
    for j in range(1,M+1):
        term=-term*zz/((2*j-1)*(2*j)); total+=term
    # M even: the next term is negative.
    return total+I(-q**(2*M+2)/factorial(2*M+2),0)

def floor_trunc(q,places):
    q=Fraction(q); return q.numerator*10**places//q.denominator

def ceil_trunc(q,places): return -floor_trunc(-Fraction(q),places)

def decimal(k,places):
    return ('-' if k<0 else '')+str(abs(k)//10**places)+'.'+str(abs(k)%10**places).zfill(places)

def export(x,places=18):
    x=I(x)
    return {'lo':str(x.lower),'hi':str(x.upper),'places':places,
            'floor':decimal(floor_trunc(x.lower,places),places),
            'ceil':decimal(ceil_trunc(x.upper,places),places)}

def self_test():
    for q,p,l,h in [(Fraction(1,8),2,12,13),(Fraction(-1,8),2,-13,-12),
                    (Fraction(-101,1000),2,-11,-10),(Fraction(-1,4),2,-25,-25)]:
        assert floor_trunc(q,p)==l and ceil_trunc(q,p)==h
    for a in range(-9,10):
        for b in range(-7,8):
            x,y=Fraction(a,7),Fraction(b,9)
            assert (I(x)+I(y)).contains(x+y)
            assert (I(x)*I(y)).contains(x*y)
            if b: assert (I(x)/I(y)).contains(x/y)
    for q in (Fraction(0),Fraction(1,9),Fraction(25,4),Fraction(4)):
        assert (I(q).sqrt()**2).contains(q)
    assert pi()>3 and pi()<Fraction(22,7)
    assert I(1).log().contains(0) and I(0).exp().contains(1)
    assert (I(2).log().exp()).contains(2)
    assert (I(Fraction(1,10)).asin().cos_small()**2).overlaps(I(Fraction(99,100)))
    for fn in (lambda:I(0).log(),lambda:I(-1).sqrt(),lambda:I(-1,1).reciprocal(),lambda:I(1).asin()):
        try: fn()
        except ValueError: pass
        else: raise AssertionError('missing domain guard')
    return 'signed arithmetic, inverse functions and domain guards all passed'

