static void putz(FILE*f,Z a){
 char b[100];int k=0;if(a<0){fputc('-',f);a=-a;}
 do{b[k++]=(char)('0'+a%10);a/=10;}while(a);
 while(k)fputc(b[--k],f);
}
static void outrow(FILE*f,int i,int j,Z l,Z h){fprintf(f,"%d %d ",i,j);putz(f,l);fputc(' ',f);putz(f,h);fputc('\n',f);}
static void product(Z l,Z h,Z a,Z b,Z *o,Z *p){
 Z q[4]={l*a,l*b,h*a,h*b};*o=*p=q[0];
 for(int k=1;k<4;k++){if(q[k]<*o)*o=q[k];if(q[k]>*p)*p=q[k];}
}
int main(void){
 enum{MAX=140100};
 int (*freq)[4]=calloc(MAX,sizeof(*freq));Z *lo=calloc(MAX,sizeof(Z)),*hi=calloc(MAX,sizeof(Z));
 assert(freq&&lo&&hi);FILE*f=fopen("OWN_FOURIER.txt","r");assert(f);
 int e[4],n=0;long long l,h;Z tail=0;
 while(fscanf(f,"%d%d%d%d%lld%lld",e,e+1,e+2,e+3,&l,&h)==6){
  assert(l<=h&&l>-(1LL<<60)&&h<(1LL<<60));int sg=0;
  for(int j=0;j<4;j++){assert(abs(e[j])<=26);if(!sg&&e[j])sg=e[j]>0?1:-1;}
  if(sg<0)continue;
  int k=sg?2:1;Z mx=absz(l)>absz(h)?absz(l):absz(h);
  if(mx*10000000000LL<((Z)1<<56)){tail+=k*mx;continue;}
  assert(n<MAX);memcpy(freq[n],e,sizeof e);lo[n]=k*(Z)l;hi[n]=k*(Z)h;n++;
 }
 assert(feof(f));fclose(f);
 int a[70][4],deg[70],nf=0;
 /* independent sorted enumeration from the enclosing0..4 cube */
 for(int d=0;d<=4;d++)for(int u=0;u<=4;u++)for(int v=0;v<=4;v++)for(int w=0;w<=4;w++)for(int z=0;z<=4;z++)if(u+v+w+z==d){a[nf][0]=u;a[nf][1]=v;a[nf][2]=w;a[nf][3]=z;deg[nf++]=d;}
 assert(nf==70);
 long long (*mon)[35]=calloc(n,sizeof(*mon));assert(mon);
 Z mass[35]={0},radmass[35]={0},fourth[35]={0};
 for(int i=0;i<n;i++)for(int j=0;j<70;j++){
  long long m=1;
  for(int k=0;k<4;k++)for(int r=0;r<a[j][k];r++)m*=freq[i][k];
  if(j<35){mon[i][j]=m;mass[j]+=(absz(lo[i])+absz(hi[i]))*absz(m);radmass[j]+=(hi[i]-lo[i])*absz(m);}
  else fourth[j-35]+=(absz(lo[i])>absz(hi[i])?absz(lo[i]):absz(hi[i]))*absz(m);
 }
 for(int j=0;j<35;j++){assert(mass[j]<((Z)1<<63));assert(radmass[j]<((Z)1<<63));assert(fourth[j]<((Z)1<<70));}
 long long tl[2][64],tu[2][64],vl[2][64],vu[2][64];
 f=fopen("TRIG_INPUTS.txt","r");assert(f);
 for(int b=0;b<2;b++)for(int k=0;k<64;k++){
  int ix,prec;assert(fscanf(f,"%d%d%lld%lld%lld%lld",&prec,&ix,&tl[b][k],&tu[b][k],&vl[b][k],&vu[b][k])==6);assert(ix==k&&prec==(b?60:40));
  assert(tl[b][k]<=tu[b][k]&&vl[b][k]<=vu[b][k]);
  assert(absz(tl[b][k])<=((Z)1<<(b?60:40))&&absz(tu[b][k])<=((Z)1<<(b?60:40)));
  assert(absz(vl[b][k])<=((Z)1<<(b?60:40))&&absz(vu[b][k])<=((Z)1<<(b?60:40)));
 }
 fclose(f);
 Z terr=0;
 for(int k=0;k<64;k++){if(tu[0][k]-tl[0][k]>terr)terr=tu[0][k]-tl[0][k];if(vu[0][k]-vl[0][k]>terr)terr=vu[0][k]-vl[0][k];}
 assert(terr<=2);
 FILE*p=fopen("PRIMARY_REPRO_JETS.txt","w"),*s=fopen("SECONDARY_REPRO_JETS.txt","w"),*o=fopen("OWN_JETS.txt","w");assert(p&&s&&o);
 f=fopen("LEAF_INPUTS.txt","r");assert(f);int id,d[4],m[4],count=0;
 while(fscanf(f,"%d%d%d%d%d%d%d%d%d",&id,d,m,d+1,m+1,d+2,m+2,d+3,m+3)==9){
  assert(id==count);int centres[4];
  for(int k=0;k<4;k++){assert(0<=d[k]&&d[k]<=5&&0<=m[k]&&m[k]<(1<<d[k]));centres[k]=(2*m[k]+1)*(1<<(5-d[k]));}
  Z B[35][64][4]={{{0}}}; /* endpoint sums separated by sign */
  for(int i=0;i<n;i++){
   int r=0;for(int k=0;k<4;k++)r+=freq[i][k]*centres[k];r=(r%64+64)%64;
   for(int j=0;j<35;j++){
