    assert((h1>=0&&h2>=0)||(h1<=0&&h2<=0));int off=h1>=0?0:2;
    B[j][r][off]+=h1;B[j][r][off+1]+=h2;
   }
  }
  for(int j=0;j<35;j++){
   Z L=0,U=0,J=0,OL=0,OU=0;
   int sign=deg[j]==1||deg[j]==2?-1:1;
   for(int r=0;r<64;r++){
    Z c0=deg[j]%2?vl[0][r]:tl[0][r],c1=deg[j]%2?vu[0][r]:tu[0][r];
    Z z0=deg[j]%2?vl[1][r]:tl[1][r],z1=deg[j]%2?vu[1][r]:tu[1][r];
    for(int off=0;off<=2;off+=2){Z ll,hh;product(B[j][r][off],B[j][r][off+1],c0,c1,&ll,&hh);L+=ll;U+=hh;product(B[j][r][off],B[j][r][off+1],z0,z1,&ll,&hh);OL+=ll;OU+=hh;}
    J+=(B[j][r][0]+B[j][r][1]+B[j][r][2]+B[j][r][3])*(c0+c1);
   }
   if(sign<0){Z z=L;L=-U;U=-z;z=OL;OL=-OU;OU=-z;J=-J;}
