   outrow(p,id,j,L,U);outrow(s,id,j,J-E,J+E);outrow(o,id,j,OL,OU);
  }
  count++;
 }
 assert(feof(f));fclose(f);fclose(p);fclose(s);fclose(o);
 f=fopen("JET_BUDGETS.txt","w");assert(f);fprintf(f,"%d %d ",count,n);putz(f,tail);fputc('\n',f);
 for(int j=0;j<35;j++){putz(f,fourth[j]);fputc('\n',f);}fclose(f);
