checks=0

def ck(v,tag):
    global checks
    if not v:raise AssertionError(tag)
    checks+=1

def cmul(a,b):return a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]
def cadd(a,b):return a[0]+b[0],a[1]+b[1]
def n2(a):return a[0]*a[0]+a[1]*a[1]
def powc(z,n):
    if n<0:return powc((z[0],-z[1]),-n)
    a=(Q(1),Q(0))
    while n:
        if n&1:a=cmul(a,z)
        z=cmul(z,z);n//=2
    return a

def val(P,z):
    a=(Q(0),Q(0))
    for e,c in P.items():
        q=(c,Q(0))
        for j,k in enumerate(e):q=cmul(q,powc(z[j],k))
        a=cadd(a,q)
    return a

def conv(P,R):
    ans={}
    for a,v in P.items():
        for b,w in R.items():
            k=tuple(x+y for x,y in zip(a,b));ans[k]=ans.get(k,Q(0))+v*w
    return ans

def adj(P):return {tuple(-j for j in e):v for e,v in P.items()}

def exact_ratio_fixture(N,ps):
    ex={};rr={};a={n:Q(1,n*n) for n in range(1,N+1)}
    for n in a:
        r=n;e=[]
        for p in ps:
            d=0
            while r%p==0:r//=p;d+=1
            e.append(d)
