    ss=[n for n in a if rr[n]==1];rough=sorted(set(rr.values()));q={r:Q(r+3,2) for r in rough};q[1]=1
    direct={}
    for r in rough:
        f={ex[n]:a[n] for n in a if rr[n]==r}
        for k,z in conv(f,adj(f)).items():direct[k]=direct.get(k,Q(0))+(1 if r==1 else -q[r])*z
    reduced={}
    for u in ss:
        for v in ss:
